"""Repair terse grammar stems and replace generic literature templates."""
import copy

LITERATURE={
'बड़े घर की बेटी':('आनंदी के मायके और ससुराल की आर्थिक स्थिति में क्या अंतर था? [2]\nघी के उपयोग पर लालबिहारी और आनंदी में विवाद क्यों हुआ? [2]\nश्रीकंठ की प्रतिक्रिया से संयुक्त परिवार पर क्या संकट आया? [3]\nआनंदी ने लालबिहारी को रोककर शीर्षक को कैसे सार्थक किया? [3]', 'आनंदी समृद्ध घर से आई थी, पर ससुराल के साधारण जीवन में ढली। घी मांस में लग जाने पर दाल में न बचा; मायके पर टिप्पणी से विवाद बढ़ा। लालबिहारी के व्यवहार पर श्रीकंठ अलग होने को तैयार हुआ। आनंदी ने क्षमा और स्नेह से लालबिहारी को जाने से रोका; बड़प्पन धन के बजाय उदार चरित्र में सिद्ध हुआ।'),
'संदेह':('रामनिहाल के मन में मनोरमा को लेकर कौन-सी शंका उत्पन्न होती है? [2]\nश्यामा की सलाह में संदेह की क्या भूमिका है? [2]\nबिना पूरे तथ्य जाने निर्णय करने का संकट पाठ के प्रसंग से समझाइए। [3]\nश्यामा के दृष्टिकोण से सहायता और निजी आकर्षण में क्या अंतर स्पष्ट होता है? [3]','रामनिहाल मनोरमा के व्यवहार और सहायता की माँग को निजी प्रेम के रूप में समझने लगता है। श्यामा उसकी धारणा पर प्रश्न उठाकर परिस्थिति समझने तथा जरूरतमंद की सहायता करने को कहती है। अधूरी जानकारी और आत्मकेंद्रित अनुमान से संबंध गलत समझे जा सकते हैं। सहायता को प्रेम का प्रमाण मानना उचित नहीं; विवेक और सहानुभूति आवश्यक हैं।'),
'भीड़ में खोया आदमी':('कहानी में भीड़ और व्यक्ति के अकेलेपन में क्या विरोध है? [2]\nभीड़ की उपस्थिति अपने-आप मानवीय संबंध क्यों नहीं बनाती? [2]\nशीर्षक के “खोया” शब्द को सामाजिक संदर्भ में समझाइए। [3]\nनगर-जीवन में पहचान और संवेदनशीलता के प्रश्न को कहानी के आधार पर स्पष्ट कीजिए। [3]','चारों ओर लोग होने पर भी व्यक्ति अपनापन और पहचान खो सकता है। शारीरिक निकटता भावनात्मक संबंध नहीं है। “खोया” व्यक्ति की उपेक्षा और आत्मीयता के अभाव को सूचित करता है। उत्तर में निर्धारित कहानी की घटनाओं से सामाजिक दूरी, संवेदनहीनता और पहचान के संकट का समर्थन अपेक्षित है; केवल भीड़ का वर्णन पर्याप्त नहीं।'),
'भेड़ें और भेड़िए':('भेड़ और भेड़िया किन प्रवृत्तियों के प्रतीक हैं? [2]\nसियार भेड़िए की छवि क्यों बदलता है? [2]\nधार्मिक या नैतिक भाषा का चुनावी प्रचार में दुरुपयोग कैसे होता है? [3]\nचुनाव के परिणाम से लेखक लोकतंत्र की किस कमजोरी पर व्यंग्य करता है? [3]','भेड़ें भोली शोषित जनता और भेड़िए हिंसक स्वार्थी शोषकों का संकेत हैं। सियार प्रचार से भेड़िए को हितैषी दिखाकर सत्ता दिलाना चाहता है। बाहरी सज्जनता और आकर्षक उपदेश असली स्वार्थ छिपाते हैं। विवेकहीन मतदाता अपने विरोधी को प्रतिनिधि चुन लेते हैं; परिणाम जनता के शोषण और प्रचार की शक्ति को उजागर करता है।'),
'दो कलाकार':('चित्रा और अरुणा की रुचियों में क्या अंतर है? [2]\nसेवा के कारण अरुणा का कला-अभ्यास किस प्रकार प्रभावित होता है? [2]\nचित्रा के चित्र और अरुणा की प्रत्यक्ष सहायता में अंतर स्पष्ट कीजिए। [3]\n“सच्चा कलाकार” विषय पर दोनों पात्रों से समर्थित निष्कर्ष दीजिए। [3]','चित्रा चित्रकला में उपलब्धि चाहती है, अरुणा जरूरतमंदों की सहायता को प्राथमिकता देती है। समय और श्रम सेवा में लगते हैं। चित्र पीड़ा का प्रभावशाली प्रतिनिधित्व कर सकता है; अरुणा पीड़ित जीवन को बदलने का प्रयत्न करती है। पाठ कलात्मक यश और मानवीय संवेदना की तुलना करता है; निष्कर्ष में कला के प्रभाव और सेवा के ठोस परिणाम दोनों का विवेचन हो।'),
'सूर के पद':('पदों में बालकृष्ण और माँ का संबंध क्या है? [2]\nबालकृष्ण की शिकायत या सफाई में बाल-स्वभाव कैसे व्यक्त होता है? [2]\nवात्सल्य भाव के दो पक्ष उदाहरण सहित स्पष्ट कीजिए। [3]\nसंवाद और बालसुलभ तर्क पदों को सजीव कैसे बनाते हैं? [3]','कृष्ण बालक और यशोदा माता के रूप में प्रस्तुत हैं। शिकायत, रूठना, अपनी सफाई देना तथा माँ से आश्वासन चाहना सहज बाल-व्यवहार है। माँ की ममता और बच्चे की निकटता वात्सल्य के आधार हैं। उत्तर में अपने निर्धारित पदों की सही घटना/भाव लें; संवाद बालक की चपलता और आत्मीय घरेलू वातावरण को मूर्त करते हैं।'),
'विनय के पद':('कवि किससे प्रार्थना करता है और उसका भाव क्या है? [2]\nविनम्रता भक्ति का आधार क्यों है? [2]\nराम की उदारता का भाव पद के आधार पर समझाइए। [3]\nदीनता और विश्वास एक-दूसरे के विरोधी न होकर पूरक कैसे हैं? [3]','भक्त राम से विनय करता है और स्वयं को उनकी कृपा का आश्रित मानता है। विनम्रता अहंकार त्यागकर समर्पण की भावना जगाती है। राम की करुणा और शरणागत के प्रति उदारता भरोसे का आधार हैं। अपनी सीमाएँ स्वीकार करना निराशा नहीं; दया पर विश्वास भक्त को आशा देता है। निर्धारित पद के सही उदाहरणों से समर्थन आवश्यक है।'),
'भिक्षुक':('भिक्षुक की शारीरिक दशा से उसकी गरीबी कैसे प्रकट होती है? [2]\nबच्चों का उसके साथ होना करुणा को कैसे गहरा करता है? [2]\nभूख और प्रतीक्षा का कोई सटीक बिंब स्पष्ट कीजिए। [3]\nकविता व्यक्तिगत दया से आगे सामाजिक संवेदना की माँग कैसे करती है? [3]','दुर्बल शरीर, फटे वस्त्र और याचना अभाव व्यक्त करते हैं। बच्चों की भूख पीढ़ियों तक फैली असुरक्षा दिखाती है। निर्धारित कविता से भूख, हाथ फैलाने या भोजन की प्रतीक्षा का सही बिंब लेकर उसका अर्थ समझाएँ। केवल दान का सामान्य उपदेश नहीं; कविता पाठक को मानवीय गरिमा, विषमता और समाज की उदासीनता पर विचार कराती है।'),
'चलना हमारा काम है':('राही का प्रतीक किसके लिए प्रयुक्त है? [2]\nचलते रहने का संकल्प किन स्थितियों में अर्थपूर्ण बनता है? [2]\nपथ की बाधाओं और जीवन-संघर्ष का संबंध स्पष्ट कीजिए। [3]\nकविता की प्रेरणा और केवल सफलता पाने की इच्छा में क्या अंतर है? [3]','राही जीवन-पथ पर आगे बढ़ते मनुष्य का प्रतीक है। कठिनाई और अनिश्चित परिणाम के बावजूद गति बनाए रखना संकल्प है। बाधाएँ संघर्ष, निराशा और सीमाओं की सूचक हैं। कर्म की निरंतरता परिणाम की गारंटी नहीं माँगती; सफलता-असफलता के बीच प्रयत्न का मूल्य स्थापित होता है। निर्धारित कविता के भावों से समर्थन दें।'),
'मातृ मंदिर की ओर':('मातृ मंदिर किसका प्रतीक है? [2]\nउसकी ओर जाने वाला मार्ग सहज क्यों नहीं है? [2]\nबाधाओं के सामने कवयित्री का संकल्प स्पष्ट कीजिए। [3]\nव्यक्तिगत सुख और देश-सेवा के बीच कविता क्या संबंध प्रस्तुत करती है? [3]','मातृ मंदिर मातृभूमि और उसकी सेवा का प्रतीक है। सेवा के मार्ग में कठिनाइयाँ और त्याग हैं। कवयित्री संकटों से विचलित होने के बजाय समर्पण के साथ आगे बढ़ना चाहती है। निजी आराम से ऊपर सामूहिक हित का भाव है। उत्तर में निर्धारित कविता की बाधाओं, संकल्प और बलिदान-भाव के विशिष्ट संकेत लें।'),
'सूखी डाली':('बेला संयुक्त परिवार की व्यवस्था से असंतुष्ट क्यों है? [2]\nदादा जी परिवार की एकता को क्यों महत्त्व देते हैं? [2]\nबेला को अलग महत्त्व देने पर उसके अनुभव में क्या परिवर्तन आता है? [3]\nसूखी डाली का प्रतीक परिवार और व्यक्ति के संबंध को कैसे स्पष्ट करता है? [3]','बेला अपने व्यक्तित्व और विचारों की उपेक्षा अनुभव करती है। दादा परिवार को परस्पर सहयोग का वृक्ष मानते हैं। विशेष व्यवहार उसे अलगाव का एहसास करा सकता है और संबंधों की वास्तविक आवश्यकता सामने आती है। शाखा वृक्ष से जुड़कर पोषण पाती है; एकता के साथ सम्मान आवश्यक है। घटनाओं के सही क्रम और बेला के परिवर्तन से उत्तर समर्थित हो।'),
'महाभारत की एक साँझ':('एकांकी का समय युद्ध की किस स्थिति से जुड़ा है? [2]\nयुधिष्ठिर और दुर्योधन की दृष्टियों में मूल अंतर क्या है? [2]\nदोषारोपण और आत्मपरीक्षण के बीच संघर्ष स्पष्ट कीजिए। [3]\nयुद्ध की जीत को नैतिक विजय मानना पाठ क्यों जटिल बनाता है? [3]','पृष्ठभूमि महाभारत युद्ध के अंतिम विनाश और दुर्योधन की पराजित अवस्था की है। दोनों पक्ष अपने आचरण और अधिकार का औचित्य प्रस्तुत करते हैं। संवाद में छल, अहंकार, अन्याय और प्रतिशोध पर प्रश्न उठते हैं। अपार जनहानि और नैतिक समझौते बाहरी विजय को सरल गौरव-कथा नहीं रहने देते। सटीक तर्क और निर्धारित संवादों का संदर्भ अपेक्षित है।'),
'दीपदान':('पन्ना धाय पर किसकी रक्षा का दायित्व है? [2]\nबनवीर से कौन-सा संकट उत्पन्न होता है? [2]\nउदयसिंह की रक्षा के लिए पन्ना के निर्णय का व्यक्तिगत मूल्य क्या है? [3]\nदीपदान शीर्षक त्याग और कर्तव्य का प्रतीक कैसे बनता है? [3]','पन्ना धाय उदयसिंह की संरक्षिका है। बनवीर सत्ता के लिए उसका जीवन नष्ट करना चाहता है। पन्ना अपने पुत्र चंदन का बलिदान सहकर उदयसिंह की रक्षा करती है। निजी मातृत्व-वेदना और राजनिष्ठ कर्तव्य का संघर्ष चरम पर पहुँचता है। दीपदान जीवन के अमूल्य दीप के अर्पण का प्रतीक बनता है; घटना का सही क्रम बताना आवश्यक है।')
}

def make_bank(seed):
    bank=copy.deepcopy(seed)
    for q in bank:
        # Seed MCQs already include their alternatives in the printed prompt.
        if q.get('options') and '\n(a)' in q['prompt']:q.pop('options')
        category=q.get('category','Practice');q['section']={'grammar':'व्याकरण','writing':'रचना और पत्र','reading':'अपठित गद्यांश','literature':'साहित्य'}.get(category,category)
        if category=='grammar' and ':' in q['prompt'] and '\n' not in q['prompt']:
            kind,word=q['prompt'].split(':',1)
            instructions={'विलोम':'का विलोम लिखिए।','पर्यायवाची':'का एक पर्यायवाची शब्द लिखिए।','विशेषण':'से विशेषण बनाइए।','भाववाचक संज्ञा':'से भाववाचक संज्ञा बनाइए।','मुहावरा':'का अर्थ लिखकर वाक्य में प्रयोग कीजिए।'}
            q['prompt']=f'“{word.strip()}” '+instructions.get(kind.strip(),f'के लिए {kind.strip()} का सही उत्तर लिखिए।')
            if kind.strip()=='मुहावरा':q['marks']=2;q['answer']+=' सही अर्थ स्पष्ट करने वाला मौलिक वाक्य भी अपेक्षित है।'
        if category=='writing' and 'चित्र' in q['topic']:q['topic']='रचना: शब्दों में दी गई परिस्थिति'
        if category=='literature' and q['topic'] in LITERATURE:
            q['prompt'],q['answer']=LITERATURE[q['topic']]
    novel=[q for q in bank if q.get('book')=='नया रास्ता']
    novel_tasks=[
      ('मीनू की शिक्षा और स्वावलंबन','मीनू के सामने विवाह के अतिरिक्त कौन-सा जीवन-लक्ष्य है? [2]\nकानून की पढ़ाई उसके लिए नया रास्ता कैसे बनती है? [2]\nपरिवार का सहयोग उसकी आकांक्षा को कैसे बल देता है? [3]\nस्वावलंबन और आत्मसम्मान के संबंध को मीनू के निर्णय से स्पष्ट कीजिए। [3]','मीनू वकील बनना चाहती है। शिक्षा उसे अपनी क्षमता सिद्ध करने और आर्थिक स्वतंत्रता का साधन देती है। परिवार की अनुमति व प्रोत्साहन मार्ग खोलते हैं। उसका मूल्य विवाह-स्वीकृति पर निर्भर नहीं रह जाता; आत्मसम्मान के साथ जीवन चुनने की शक्ति बढ़ती है।'),
      ('मीनू और विवाह-संबंधी पूर्वाग्रह','मीनू के विवाह में बाहरी रूप को लेकर कौन-सा पूर्वाग्रह दिखाई देता है? [2]\nऐसी अस्वीकृति उसके मन को कैसे प्रभावित करती है? [2]\nव्यक्ति की योग्यता और रूप के मूल्यांकन में अंतर स्पष्ट कीजिए। [3]\nमीनू की उपलब्धि सामाजिक मान्यताओं को कैसे चुनौती देती है? [3]','साँवले रंग और रूप के आधार पर मूल्यांकन उसे आहत करता है। पढ़ाई, संवेदना और परिश्रम उसका वास्तविक व्यक्तित्व सिद्ध करते हैं। पेशेवर सफलता से योग्यता का स्वतंत्र मूल्य सामने आता है; विवाह ही स्त्री की उपलब्धि का एकमात्र मानदंड नहीं रहता।'),
      ('नया रास्ता: शीर्षक और सामाजिक दृष्टि','उपन्यास की नायिका का नाम और पेशेवर लक्ष्य लिखिए। [2]\nपुरानी सामाजिक कसौटियों से उसका संघर्ष क्या है? [2]\nशिक्षा से मिलने वाले आत्मविश्वास का महत्व स्पष्ट कीजिए। [3]\nशीर्षक में नये रास्ते को केवल विवाह न मानने के दो कारण दीजिए। [3]','नायिका मीनू वकालत का लक्ष्य रखती है। रूप, दहेज और विवाह-केंद्रित मूल्यांकन के विरुद्ध शिक्षा व स्वावलंबन उसे अपनी पहचान देते हैं। शीर्षक व्यक्तिगत निर्णय और स्त्री की क्षमता को मान्यता देने वाले सामाजिक परिवर्तन का संकेत है। निर्धारित अध्याय 14–26 के सही प्रसंगों से उत्तर समर्थित करें।')]
    for q,(title,prompt,answer) in zip(novel,novel_tasks):q.update(topic=title,prompt=prompt,answer=answer)
